'use client';

import { useMemo } from 'react';
import GridMotion from './GridMotion';
// Generated by scripts/gen-culturals.mjs (runs before dev/build): every photo in public/assets/culturals.
import photos from '@/data/culturals.json';

const ROWS = 4;
const ALT = 'TKM MUN Cultural Night performance';

// Deal the photos round-robin into rows so every photo appears (and no photo sits beside itself).
// Each row is then repeated so its strip is long enough to loop seamlessly on wide screens.
// Photos pinned to a specific row (0 = top). Row 1 is one of the two middle rows.
const PINNED = [{ match: 'WhatsApp Image 2026-11-04 at 12.14.14 AM', row: 1 }];

function buildRows(list) {
  const pinned = PINNED.map((p) => ({ ...p, src: list.find((src) => src.includes(p.match)) })).filter((p) => p.src);
  const rest = list.filter((src) => !pinned.some((p) => p.src === src));
  const rows = Array.from({ length: ROWS }, () => []);
  rest.forEach((src, i) => rows[i % ROWS].push(src));
  // Drop each pinned photo into the middle of its row's strip.
  pinned.forEach((p) => rows[p.row].splice(Math.floor(rows[p.row].length / 2), 0, p.src));
  return rows.map((row, r) => {
    if (!row.length) return row;
    // Offset each row so the same photo isn't directly above/below its neighbour at the start.
    const shift = (r * 2) % row.length;
    const rotated = [...row.slice(shift), ...row.slice(0, shift)];
    return [...rotated, ...rotated];
  });
}

function Tile({ src }) {
  return (
    <div className="group relative h-full w-[170px] shrink-0 overflow-hidden sm:w-[230px] lg:w-[290px] rounded-[5px] border border-gold/35 bg-maroon-dark">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        alt={ALT}
        loading="lazy"
        decoding="async"
        draggable={false}
        className="absolute inset-0 h-full w-full object-cover sepia-[.1] transition-[filter] duration-500 group-hover:sepia-0"
      />
      <div className="pointer-events-none absolute inset-0 bg-maroon-dark/[0.07] transition-opacity duration-500 group-hover:opacity-0" />
    </div>
  );
}

export default function CulturalGallery() {
  const rows = useMemo(
    () => buildRows(photos).map((row, r) => row.map((src, i) => <Tile key={`${r}-${i}-${src}`} src={src} />)),
    []
  );

  return (
    <section id="culturals" className="relative z-10 mx-auto max-w-7xl px-5 py-16 md:px-12 md:py-24">
      <div className="relative h-[78svh] min-h-[460px] overflow-hidden rounded-lg border border-gold/25 bg-oxblood md:h-[90vh]">
        <GridMotion rows={rows} gradientColor="rgba(42, 19, 18, 1)">
          {/* Blend into the sections above and below. */}
          <div className="pointer-events-none absolute inset-x-0 top-0 z-[3] h-[14%] bg-gradient-to-b from-oxblood to-transparent" />
          <div className="pointer-events-none absolute inset-x-0 bottom-0 z-[3] h-[14%] bg-gradient-to-t from-oxblood to-transparent" />

          <div className="pointer-events-none absolute inset-0 z-[4] flex items-center justify-center px-6">
            <div
              className="text-center"
              style={{
                background: 'radial-gradient(ellipse at center, rgba(42,19,18,0.7) 0%, rgba(42,19,18,0.45) 40%, rgba(42,19,18,0) 70%)',
                padding: 'clamp(2.5rem, 6vw, 4.5rem) clamp(1rem, 6vw, 4rem)',
                maxWidth: '100%',
              }}
            >
              <span className="font-display text-[10px] font-bold uppercase tracking-[0.25em] text-gold-light">After the Resolutions</span>
              <h2 className="mt-1 font-cormorant text-3xl font-semibold uppercase tracking-[0.18em] text-gold-light sm:text-4xl lg:text-5xl [text-shadow:0_2px_14px_rgba(40,16,12,0.9)]">
                Last MUN Cultural Night
              </h2>
              <div className="mx-auto mt-4 flex items-center justify-center gap-3" aria-hidden="true">
                <span className="h-px w-12 bg-gold/70 md:w-20" />
                <span className="h-1.5 w-1.5 rotate-45 bg-gold" />
                <span className="h-px w-12 bg-gold/70 md:w-20" />
              </div>
              <p className="mx-auto mt-4 max-w-md text-base text-cream md:text-lg [text-shadow:0_1px_10px_rgba(40,16,12,0.95)]">
                An evening of music, dance and drama once the committees adjourned.
              </p>
            </div>
          </div>
        </GridMotion>
      </div>
    </section>
  );
}
